{
  "findings": [
    {
      "check_id": "CKV_AWS_40",
      "title": "Ensure IAM policies are attached only to groups or roles",
      "resource": "aws_iam_user_policy_attachment.privesc15-PassExistingRoleToNewLambdaThenInvoke-user-attach-policy",
      "severity": "MEDIUM",
      "explanation": "Attaching IAM policies directly to users increases the risk of privilege mismanagement and makes it harder to audit permissions. Policies should be attached to groups or roles instead."
    }
  ],
  "patched_code": "resource "aws_iam_group" "privesc15-PassExistingRoleToNewLambdaThenInvoke-group" {
  name = "privesc15-PassExistingRoleToNewLambdaThenInvoke-group"
}

resource "aws_iam_group_policy_attachment" "privesc15-PassExistingRoleToNewLambdaThenInvoke-group-attach-policy" {
  group      = aws_iam_group.privesc15-PassExistingRoleToNewLambdaThenInvoke-group.name
  policy_arn = aws_iam_policy.privesc15-PassExistingRoleToNewLambdaThenInvoke.arn
}

resource "aws_iam_user_group_membership" "privesc15-PassExistingRoleToNewLambdaThenInvoke-user-group-membership" {
  user = aws_iam_user.privesc15-PassExistingRoleToNewLambdaThenInvoke-user.name
  groups = [
    aws_iam_group.privesc15-PassExistingRoleToNewLambdaThenInvoke-group.name
  ]
}",
  "fix_summary": "Replaced the direct attachment of the IAM policy to the user with a group-based approach. Created a new IAM group, attached the policy to the group, and added the user to the group to maintain the same permissions."
}
